ROOT=Path(__file__).resolve().parents[1]
CROSS='https://support.2k.com/hc/en-us/articles/35232640119443-Risk-of-Rain-2-Crossplay-and-You-An-Epic-Tale'
GEN='https://support.2k.com/hc/en-us/articles/48628339700371-Risk-of-Rain-2-The-Future-of-Risk-of-Rain-2-on-Gen-8-Consoles'
STEAM='https://store.steampowered.com/app/632360/Risk_of_Rain_2/'
WIKI='https://riskofrain2.wiki.gg/wiki/'
PATCH='https://steamcommunity.com/games/632360/announcements/detail/4608959311789637971'
ART='https://steamcommunity.com/games/632360/announcements/detail/2098055393562282872'
AD='<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'
ROUTES=['/risk-of-rain-2/crossplay/','/risk-of-rain-2/gold-portal/','/risk-of-rain-2/ru/bulwarks-ambry/']
def ext(url,label):return f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">{label} ↗</a>'
def ref(n):return f'<sup class="ref"><a href="#source-{n}" aria-label="Source {n}">[{n}]</a></sup>'
def table(head,rows):return '<div class="table-wrap" role="region" aria-label="Scrollable comparison" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def shell(route,title,desc,h1,answer,parts,sources,ru=False,script=False):
 nav=navigation(route)
 body=''.join(f'<section id="{i}"><h2>{h}</h2>{t}</section>' for i,h,t in parts)
 labels=['Crossplay & edition check','Gold Portal → False Son','Хранилище укрепления · русский']
 related=''.join(f'<a href="{u}"'+(' lang="ru"' if '/ru/' in u else ' lang="en"')+f'>{t}</a>' for u,t in zip(ROUTES,labels) if u!=route)
 source='<section class="sources" id="sources"><h2>'+('Источники и проверка' if ru else 'Sources &amp; verification')+'</h2><ol>'+''.join(f'<li id="source-{i}">{ext(u,l)} — {d}</li>' for i,(u,l,d) in enumerate(sources,1))+'</ol><a href="#guide">'+('К началу ↑' if ru else 'Back to guide ↑')+'</a></section>'
 html=f'''<!doctype html><html lang="{'ru' if ru else 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="https://megabonk.org{route}"><meta property="og:type" content="article"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="https://megabonk.org{route}"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/risk-of-rain-2/site.css">{AD}{'<script defer src="/assets/risk-of-rain-2/compatibility.js"></script>' if script else ''}</head><body class="guide-layout ror-guide"><a class="skip" href="#main">{'К содержанию' if ru else 'Skip to content'}</a><header class="top"><div class="wrap"><a class="brand" href="/risk-of-rain-2/"><span>Risk of Rain 2<small>{'Megabonk.org · игровые гайды' if ru else 'Megabonk.org · Independent guides'}</small></span></a><nav class="desktop-nav" aria-label="{'Навигация сайта · английские разделы' if ru else 'Main navigation'}">{nav}</nav><details class="mobile-nav"><summary>{'Меню' if ru else 'Menu'}</summary><nav class="mobile-links" aria-label="{'Мобильная навигация · английские разделы' if ru else 'Mobile navigation'}">{nav}</nav></details></div></header><main class="wrap" id="main"><header class="article-head" id="guide"><p class="eyebrow">{'НЕЗАВИСИМЫЙ ГАЙД' if ru else 'INDEPENDENT PLAYER GUIDE'} · RISK OF RAIN 2</p><h1>{h1}</h1><div class="answer">{answer}</div><p class="byline">{'Редакция Megabonk.org · проверено 5 ноября 2026 · без собственного прохождения' if ru else 'By Megabonk.org · checked 5 November 2026 · document-based, not a playtest'}</p></header><div class="article-layout"><nav class="toc" aria-label="{'На этой странице' if ru else 'On this page'}"><strong>{'На этой странице' if ru else 'On this page'}</strong>{''.join(f'<a href="#{i}">{h}</a>' for i,h,_ in parts)}</nav><article class="prose">{body}{source}<section><h2>{'Другие задачи · гайды на английском' if ru else 'Related tasks'}</h2><div class="related">{related}</div></section></article></div></main><footer class="footer"><div class="wrap footer-grid"><div><strong>Megabonk.org</strong><p>{'Независимая редакция; не связана с Hopoo Games, Gearbox или 2K.' if ru else 'Independent editorial. Not affiliated with Hopoo Games, Gearbox or 2K.'}</p><a href="/#wiki-start">{'Другие игры и гайды (EN)' if ru else 'More games &amp; guides'} →</a></div><nav aria-label="{'О сайте · страницы на английском' if ru else 'Site information'}"><a href="/about/">{'О сайте' if ru else 'About'}</a><a href="/contact/">{'Контакты' if ru else 'Contact'}</a><a href="/privacy-policy#risk-of-rain-2">{'Конфиденциальность' if ru else 'Privacy'}</a></nav></div></footer></body></html>'''
 return decorate(route,html)

def crossplay():
 opts=[('steam-on','Steam · crossplay ON'),('steam-off','Steam · crossplay OFF'),('steam-unknown','Steam · setting not checked'),('epic','Epic Games Store · PC'),('ps4','PlayStation 4'),('ps5','PlayStation 5'),('one','Xbox One'),('series','Xbox Series X|S'),('switch','Nintendo Switch'),('switch2','Switch 2 / edition not confirmed'),('other','Another or unspecified edition')]
 options='<option value="">Choose a copy…</option>'+''.join(f'<option value="{v}">{t}</option>' for v,t in opts)
 tool=f'''<form class="tool" id="pair-form"><div class="tool-grid"><label>Player 1: copy and setting<select name="player1" required>{options}</select></label><label>Player 2: copy and setting<select name="player2" required>{options}</select></label></div><button type="submit">Check our copies</button><button type="reset">Clear choices</button><p role="status" aria-live="polite" id="pair-status">Choose both copies. Steam players: check the setting in your own game.</p><div class="result" id="pair-result" hidden><strong id="pair-summary"></strong><p id="pair-next"></p><button type="button" id="pair-open">View result &amp; next steps</button></div><noscript><p>Use the documented-pairs table below; it contains the same rules without JavaScript.</p></noscript></form><dialog id="pair-dialog" aria-labelledby="pair-title"><div class="dialog-body"><button type="button" id="pair-close">Close result</button><h3 id="pair-title"></h3><p id="pair-text"></p><p id="pair-action"></p><p>Rules checked 5 November 2026. This does not contact a lobby or test your connection.</p><a href="#pairs" id="pair-table">Compare the source table</a></div></dialog>'''
 parts=[('check','Check both copies',f'<p>This check combines the exact stores, Steam crossplay settings and console generation. It reports what the reviewed documents establish; <strong>unconfirmed is not the same as impossible</strong>. It does not check saves, mods or server reachability. Nothing you select is stored. {ref(1)}{ref(2)}</p>'+tool),
 ('pairs','Documented pairs and limits',table(['Copies','What the documentation supports','Next step'],[
 ('Steam + Epic on PC','Supported cross-store route. Steam must opt in. '+ref(1),'Enable crossplay, restart, then use the documented invitation/lobby route.'),
 ('Steam + Steam, same setting','Both opted in can connect; both opted out can keep normal Steam play. '+ref(1),'If settings differ, agree on one mode and restart.'),
 ('PS4 + PS5; Xbox One + Series','Generation split announced; timing tied to the next console update. '+ref(2),'Check both installed editions and their patch notes. This guide does not verify whether that split has reached your copies.'),
 ('PC + console; PlayStation + Xbox; Switch + another family','No cross-family route established by these sources. '+ref(1)+ref(2),'Do not purchase a second copy on the assumption that a room code enables it.'),
 ('Same exact console edition','Use that edition’s online multiplayer; cross-generation and cross-family are separate questions. '+ref(3),'Match the actual game edition and version; check any platform online-service requirement.'),
 ('Switch 2 or an unspecified edition','Not established here as a native Switch 2 release or new crossplay route. '+ref(2),'Identify the running edition before relying on backward compatibility or a store listing.')])),
 ('steam-epic','Connect Steam and Epic',f'<ol><li>On Steam, open the game and check its crossplay preference in settings or the first multiplayer prompt. Choose <strong>ON</strong> when an Epic player is joining.</li><li>Restart after changing that preference. Other Steam friends must also opt in to join that crossplay session.</li><li>To invite Epic friends, use the account-linking choice in Options. The publisher describes a browser step linking Steam and Epic accounts.</li><li>Use the in-game invitation, Epic overlay, or the other player’s copied <strong>Lobby ID</strong> where that lobby is public.</li></ol><p>These are the publisher’s instructions, updated 4 September 2025 and rechecked 5 November 2026. They establish the supported route, not a guarantee that a particular network session works. {ref(1)}</p><p>If only Steam friends are playing, both may choose OFF instead. Turning it off on one PC while the other stays ON separates them; turning it off also removes the Steam-to-Epic route. Treat “disable crossplay” advice according to who actually needs to join. {ref(1)}</p>'),
 ('editions','PS4, Switch and newer consoles',f'<p>2K’s console notice, updated 8 October 2026, says future content and updates focus on PC, PS5 and Xbox Series X|S. Xbox One, PS4 and the original Switch can still play the content they have, but a newer DLC appearing in a bundle does not establish that it runs on an older console. {ref(2)}</p><p>The same notice says PS4–PS5 and Xbox One–Series multiplayer will separate with the next console update, while retaining conditional wording about when it happens. Check the actual installed version on both machines before planning cross-generation play. We have not tested console matchmaking or confirmed the rollout on each platform. {ref(2)}</p><p>For PlayStation, the official product page grants PS4 and PS5 versions to the purchaser’s same PSN account. That entitlement is different from two players being able to connect across versions. {ref(3)}</p>'),
 ('help','A compatible pair still cannot join?',f'<ol><li>Confirm the store and installed edition on both devices. A Windows PC does not identify its storefront.</li><li>Compare Steam settings, restart after changes, then try the publisher’s lobby/invite route again.</li><li>Record both versions and the exact point of failure: missing lobby, failed join or disconnect after the run begins. Those are different symptoms.</li><li>If the documented pair still fails, send those details to {ext('https://support.2k.com/hc/en-us/requests/new','2K · support request')}. Avoid deleting saves or removing game DLLs based on an unrelated old post.</li></ol><p>This page gives confirmed compatibility checks, not a universal disconnect fix. The check does not install mods or change your game. {ref(1)}</p>')]
 return shell(ROUTES[0],'Risk of Rain 2 Crossplay: Check Both Copies','Check Risk of Rain 2 crossplay by both players’ stores, Steam settings and console generations. See confirmed routes and edition limits before joining.','Risk of Rain 2 crossplay: can your copies connect?',f'<p><strong>Steam and Epic can play together on PC, but Steam crossplay settings must match the session.</strong> Console generations have separate limits. Choose both copies below; a shared game title or room code does not settle compatibility. {ref(1)}{ref(2)}</p>',parts,[(CROSS,'2K · Crossplay and You','Little Sister; updated 4 September 2025. Steam/Epic, matching preferences and invitations; rechecked 5 November 2026. No live session test.'),(GEN,'2K · Gen 8 console notice','Updated 8 October 2026; read 5 November. Future content and conditional cross-generation split; rollout not tested.'),('https://www.playstation.com/en-us/games/risk-of-rain-2/','PlayStation · Risk of Rain 2','PS4/PS5 product entitlement and online product information; read 5 November 2026. Not evidence for cross-family matchmaking.'),(STEAM,'Steam · Risk of Rain 2','Official multiplayer game screenshot © Hopoo Games / Gearbox. Marketing capture, build unspecified; not a settings screenshot or our session.')],script=True)

def gold():
 parts=[('start','Choose your starting point',table(['Your run right now','Do this next','Why'],[
 ('No Halcyon Seed; an Altar of Gold is available','Pay it, complete the Teleporter event, then take the Gold Portal.','Do not leave through the normal Teleporter first. '+ref(1)),
 ('No altar; you can enter the Bazaar','Check the Lunar Seer for Gilded Coast.','It is an alternative offer, not a guaranteed destination. '+ref(1)),
 ('Already holding Halcyon Seed','Keep it and proceed toward Prime Meridian with Seekers enabled.','The unlock needs the seed at the final fight; a second Gilded Coast visit is not the goal. '+ref(2)),
 ('Already on the Path of the Colossus without a seed','Check a Halcyon Shrine on that route for the documented gold-orb/Gold Portal branch.','The challenge guide describes this recovery route; do not confuse a normal green route with the Gold Portal. '+ref(2))])+'<p><strong>A Gold Portal is the entrance, not the unlock.</strong> Your checkpoints are Gilded Coast → seven active beacons → Halcyon Seed → False Son with the seed. A portal visit without collecting the seed leaves the final prerequisite incomplete.</p>'),
 ('beacons','At Gilded Coast: all seven beacons',f'<ol><li>Locate the <strong>seven Halcyon Beacons</strong> and gather gold for their activation costs before committing to the fight.</li><li>The fourth activated beacon summons Aurelionite, but it does not make her vulnerable. Activate all seven.</li><li>Damage Aurelionite while all seven remain active. If the beacons reset, pay to reactivate them and reopen the damage window.</li><li>After winning, pick up <strong>Halcyon Seed</strong>. Check your inventory before choosing an exit.</li></ol><p>These rules come from the community Wiki’s Gilded Coast documentation, with the basic sequence also described by the independent Gold Portal guide. We did not play this fight ourselves. The official image above is a historical beacon-rendering comparison, useful for recognizing the objects, not a current spawn map. {ref(1)}{ref(3)}{ref(4)}</p>'),
 ('exit','Pick the exit for your goal',f'<p>With <strong>Seekers of the Storm enabled</strong>, the challenge documentation describes a green exit toward the Path of the Colossus when Gilded Coast was entered from a stage 1, 2 or 3 environment. Keep track of where you entered; do not plan around every Gilded Coast visit producing that same continuation. {ref(2)}</p><p>If you only wanted the boss item, collecting it completes that goal. If you want the False Son survivor, preserve the seed and continue along the Colossus route to <strong>Prime Meridian</strong>. Do not convert the seed away as if it were spare loot. This guide does not promise a guaranteed altar, Bazaar offer or fixed map sequence. {ref(1)}{ref(2)}</p><p><strong>Keep taking the green route, not the ordinary Teleporter:</strong> its normal sequence is Reformed Altar → Treeborn Colony (or its loop variant Golden Dieback) → Prime Meridian. A later entry can skip earlier route stages. On Reformed Altar or Treeborn Colony, finish the event and enter the Green Portal to stay on the Colossus path; choosing the ordinary Teleporter sends you back to the normal stage route. {ref(5)}</p>'),
 ('false-son','Complete Purified Freedom',f'<p><strong>Defeat False Son at Prime Meridian while carrying the Halcyon Seed obtained from Gilded Coast.</strong> This is the Seekers of the Storm challenge that unlocks the playable False Son. Merely beating Aurelionite, opening the green route, or visiting Prime Meridian is not the same result. {ref(2)}</p><p>The community challenge guide says False Son takes the seed in the third phase and summons an <strong>enemy Aurelionite</strong>. Plan for that extra threat rather than expecting your Gilded Coast ally to protect you. Its stated completion condition is defeating False Son; the summoned Aurelionite need not be killed first and can remain dangerous afterward. {ref(2)}</p><p>This final-phase behavior is a single community reference, checked through its indexed text on 5 November 2026; it was not independently reproduced here. Verify the challenge notification after the fight before treating the survivor as unlocked. We do not promise a particular damage build, difficulty setting or multiplayer credit outcome.</p>'),
 ('stuck','Check the missing checkpoint',table(['Symptom','Check before restarting'],[
 ('Paid the gold altar but saw no portal','Finish that stage’s Teleporter event and look for the separate Gold Portal before advancing. '+ref(1)),
 ('Aurelionite takes no damage','Are all seven beacons active, rather than only the four that summon her? Have they reset? '+ref(1)),
 ('Won at Gilded Coast, no desired continuation','Check entry-stage conditions and Seekers being enabled; collecting a seed does not guarantee the same exit on every visit. '+ref(2)),
 ('Beat False Son, survivor still locked','Check that the seed was actually collected and retained into that fight, then inspect the challenge result. An unresolved version/account problem needs support, not a claim that another Gilded Coast visit always fixes it. '+ref(2))]))]
 return shell(ROUTES[1],'Risk of Rain 2 Gold Portal to False Son: Route Guide','Follow the Risk of Rain 2 Gold Portal route through Gilded Coast, seven beacons and Halcyon Seed to the Purified Freedom survivor unlock.','Gold Portal → Halcyon Seed → False Son',f'<p><strong>Pay an Altar of Gold, finish its Teleporter event, then enter the Gold Portal.</strong> At Gilded Coast, activate all seven beacons and defeat Aurelionite for Halcyon Seed. For Purified Freedom, keep that seed and defeat False Son at Prime Meridian with Seekers of the Storm enabled. {ref(1)}{ref(2)}</p>',parts,[(WIKI+'Gilded_Coast','Risk of Rain 2 Wiki · Gilded Coast','Community reference; indexed text checked 5 November 2026, direct page returned 403. Entrance alternatives, seven beacons, shield and seed.'),(WIKI+'Purified_Freedom','Risk of Rain 2 Wiki · Purified Freedom','Community single source for the precise challenge and final phase; indexed text checked 5 November 2026. Seekers route, not a reproduced unlock.'),('https://riskrain.skin/gold-portal/','riskrain.skin · Gold Portal','Independent guide; basic altar/beacon/seed sequence, read 5 November 2026. Not a second playtest.'),(PATCH,'Risk of Rain team on Steam · v1.3.4','10 September 2024 official beacon shader comparison © Gearbox Software. Original OLD/NEW labels retained; visual identification only, not current-route verification.'),(WIKI+'Path_of_the_Colossus','Risk of Rain 2 Wiki · Path of the Colossus','Indexed route description checked 5 November 2026; stage order, later entries and green-portal versus normal-Teleporter choice.')])

def ambry():
 parts=[('terms','Как называется нужное место',f'<p><strong>Хранилище укрепления</strong>, «Хранилище Бастиона» и английское <strong>Bulwark’s Ambry</strong> в найденных русских материалах относятся к скрытому миру с испытанием артефакта. Центральная сфера — <strong>Artifact Reliquary</strong>. Предмет для взаимодействия — <strong>Artifact Key</strong>, а не «ключ Vengeance»: Vengeance — название отдельного артефакта. {ref(1)}{ref(2)}{ref(3)}</p><p>Ниже — обычная последовательность испытания, а не список всех кодов или обещание одинаковых правил для каждого артефакта. Английские имена оставлены рядом с русскими, чтобы вы могли сопоставить интерфейс и источник. Основа — материалы Wiki, проверенные по индексированному тексту 5 ноября 2026; собственного прохождения нет.</p>'),
 ('entry','Вход: сначала определите пятый этап',table(['Где вы оказались','Где искать вход','Что нажать'],[
 ('Sky Meadow · Небесное поле','Compound Generator под основной частью карты.','Введите выбранный код в сетке 3×3, затем взаимодействуйте с ноутбуком. '+ref(1)+ref(4)),
 ('Helminth Hatchery · Seekers of the Storm','Compound Generator в нише на самом верхнем уровне.','Та же последовательность: код → ноутбук → Artifact Portal. '+ref(5)),
 ('Обычный Teleporter','Это отдельный объект, а не машина кодов.','Не уходите с этапа обычным телепортом, если цель — испытание выбранного артефакта. '+ref(4))])+'<p>Сначала выберите артефакт и его код. Вводы переключаются по кругу: квадрат → круг → треугольник → ромб. После подтверждения верного кода открывается отдельный портал. При неверном коде исправьте сетку и подтвердите снова; сам факт нажатия ноутбука не означает, что портал открылся. '+ref(4)+ref(5)+'</p><p>Артефакт, который вы пытаетесь получить, действует внутри испытания вместе с уже включёнными модификаторами. Поэтому заранее прочитайте его эффект, а для первого знакомства не добавляйте сразу несколько незнакомых правил. '+ref(4)+'</p>'),
 ('keys','Испытание: ключ → сфера → новый ключ',f'<ol><li>Найдите первый <strong>Artifact Key</strong> на возвышении перед центральной сферой.</li><li>Подберите его и взаимодействуйте с <strong>Artifact Reliquary</strong>. Это запускает противников и снимает часть здоровья сферы.</li><li>Убивайте появившихся врагов, подберите выпавший новый ключ и вернитесь к сфере. Обычная стрельба по ней не заменяет взаимодействие с ключом.</li><li>Повторяйте цикл. В стандартном случае нужны четыре последовательных применения, но особые модификаторы могут повлиять на бой.</li><li>После разрушения сферы <strong>подберите сам артефакт</strong>, затем уходите через появившийся портал.</li></ol><p>При применении ключа другие уже появившиеся ключи убираются — в том числе у остальных игроков и на земле. Не собирайте запас на несколько будущих применений: сначала сдайте текущий, потом ищите следующий. {ref(2)}{ref(3)}</p><p>Подробная механика ключей опирается на один общественный Wiki-проект, а не на несколько независимых тестов. Здесь нет гарантии одинакового результата во всех версиях и со всеми наборами артефактов. {ref(2)}</p>'),
 ('stuck','Что проверять, если испытание остановилось',table(['Что видно','Следующая проверка'],[
 ('Врагов ещё нет','Был ли поднят первый ключ и выполнено взаимодействие со сферой? Одного входа в мир недостаточно. '+ref(2)),
 ('Враги есть, здоровье сферы не убывает','Ищите выпавший ключ и несите его к сфере, вместо стрельбы по неуязвимой цели. '+ref(2)),
 ('Команда разошлась и враги не появляются','Вернитесь ближе к главной платформе: Wiki отмечает прекращение спавна, когда все игроки слишком далеко. '+ref(2)),
 ('Ключи пропали у напарника','После применения одного ключа остальные удаляются; это предусмотренное ограничение накопления. '+ref(3)),
 ('Сфера разрушена, но задача не завершена','Подберите открывшийся артефакт. Посещение локации само по себе его не разблокирует. '+ref(4))])+'<p>Если после этих проверок цель по-прежнему не меняется, запишите версию игры, выбранный артефакт и состояние задания. Этот гайд не обещает исправить любой баг спавна и не предлагает менять сохранения.</p>'),
 ('exit','Награда и выход',f'<p>После получения артефакта портал возвращает забег к первому набору этапов. Это продолжение с циклом, а не обычный переход к следующему по номеру окружению. В новом забеге артефакт можно выбрать при настройке; его разблокировка не означает, что он будет автоматически включён всегда. {ref(4)}</p><p>Внешний вид Хранилища может отличаться: Seekers добавляет варианты Aphelian Research, Tar Research и Wisp Research. Ориентируйтесь на центральный объект и текущее задание, а не на предположение, что любая платформа совпадёт со старой картинкой. {ref(1)}</p>')]
 return shell(ROUTES[2],'Risk of Rain 2: Хранилище укрепления — как пройти','Как попасть в Хранилище укрепления в Risk of Rain 2, найти Artifact Key, завершить испытание у центральной сферы и забрать артефакт перед выходом.','Хранилище укрепления в Risk of Rain 2: вход и испытание',f'<p><strong>Откройте Artifact Portal через Compound Generator на пятом этапе, затем применяйте Artifact Key к центральной сфере.</strong> Урон оружием её не заменяет: новые ключи выпадают из врагов. Разрушив сферу, заберите артефакт перед выходом. {ref(1)}{ref(2)}</p>',parts,[(WIKI+'Bulwark%27s_Ambry','Risk of Rain 2 Wiki · Bulwark’s Ambry','Общественный справочник: входы и варианты мира; индексированный текст 05.11.2026, прямое чтение 403.'),(WIKI+'Artifact_Reliquary','Risk of Rain 2 Wiki · Artifact Reliquary','Цикл взаимодействий и остановка спавна вдали от платформы; тот же Wiki, не независимый игровой тест.'),(WIKI+'Artifact_Key','Risk of Rain 2 Wiki · Artifact Key','Название и удаление ключей при использовании; индексированный текст 05.11.2026.'),(WIKI+'Artifacts','Risk of Rain 2 Wiki · Artifacts','Коды, действующий модификатор, получение награды и выход; проверено 05.11.2026.'),(WIKI+'Helminth_Hatchery','Risk of Rain 2 Wiki · Helminth Hatchery','Ниша с Compound Generator на верхнем уровне; Seekers of the Storm. Индексированный текст 05.11.2026.')],ru=True)

def build():
 from ror2_hub import render
 hub=ROOT/'risk-of-rain-2/index.html'
 hub.parent.mkdir(parents=True,exist_ok=True)
 write_html(hub,render(shell),encoding='utf8')
 for route,page in zip(ROUTES,[crossplay(),gold(),ambry()]):
  f=ROOT/route.strip('/')/'index.html';f.parent.mkdir(parents=True,exist_ok=True);write_html(f,page,encoding='utf-8')
 f=ROOT/'index.html';s=f.read_text(encoding='utf-8')
 if 'id="ror2-crossplay-entry"' not in s:
  cards=[('ror2-crossplay-entry',ROUTES[0],'Risk of Rain 2: play together','Check both stores, Steam crossplay settings and console generation limits.','Check our copies'),('ror2-gold-entry',ROUTES[1],'Risk of Rain 2: Gold Portal route','Follow seven beacons and Halcyon Seed to the False Son unlock.','Plan the unlock route'),('ror2-ambry-entry',ROUTES[2],'Хранилище укрепления · Risk of Rain 2','Вход через пятый этап, Artifact Key и награда испытания. Гайд на русском.','Пройти испытание')]
  block=''.join(f'<a class="route-card" id="{i}" href="{u}"'+(' lang="ru"' if '/ru/' in u else '')+f'><h3>{h}</h3><p>{d}</p><span class="route-link">{t} →</span></a>' for i,u,h,d,t in cards)
  assert '<div class="route-grid">' in s;s=s.replace('<div class="route-grid">','<div class="route-grid">'+block,1)
 write_html(f,s,encoding='utf-8')
 f=ROOT/'privacy-policy.html';s=f.read_text(encoding='utf-8')
 if 'id="risk-of-rain-2"' not in s:s=s.replace('</body>','<h2 id="risk-of-rain-2">Risk of Rain 2 guides and copy compatibility check</h2><p>Updated 5 November 2026. The copy check combines the selections locally in your browser and displays documentation-based advice. It does not store selections, upload them, access a game account, modify saves or connect to a lobby. This guide embeds no Risk of Rain 2 game or video. Publisher, community and support links lead to external services when followed. Existing site analytics and advertising apply as described above.</p></body>',1)
 write_html(f,s,encoding='utf-8')
 print('Built all 3 Risk of Rain 2 task pages and idempotent root/privacy patches.')
if __name__=='__main__':build()
